package com.farmplanner;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * In de bank: kader om alles wat je volgens het plan moet meenemen.
 * In je inventory: kader om de teleport en het zaad van de huidige stap.
 */
public class BankHighlightOverlay extends WidgetItemOverlay
{
	private final FarmPlannerPlugin plugin;

	@Inject
	BankHighlightOverlay(FarmPlannerPlugin plugin)
	{
		this.plugin = plugin;
		showOnBank();
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!plugin.getConfig().highlightBank())
		{
			return;
		}
		boolean inInventory = widgetItem.getWidget() != null
			&& WidgetUtil.componentToInterface(widgetItem.getWidget().getId()) == InterfaceID.INVENTORY;
		boolean highlight = inInventory
			? plugin.isSaplingActionItem(itemId)
				|| plugin.getInventoryHighlightIds().contains(itemId) || plugin.isCurrentTeleportItem(itemId)
			: plugin.getBankHighlightIds().contains(itemId);
		if (!highlight)
		{
			return;
		}
		Rectangle b = widgetItem.getCanvasBounds();
		Color c = plugin.getConfig().highlightColor();
		graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.min(60, c.getAlpha())));
		graphics.fill(b);
		graphics.setColor(c);
		graphics.setStroke(new BasicStroke(2));
		graphics.drawRect(b.x, b.y, b.width - 1, b.height - 1);
	}
}

package com.farmplanner;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** Het resultaat: route-stappen, wat je moet meenemen, en waarschuwingen. */
public final class FarmPlan
{
	public static final class Step
	{
		private final Patch patch;
		private final String teleport;
		private final String seed;
		private final String compost;
		private TeleportOption teleportOption;
		private String teleportItem;
		private int teleportItemId = -1;
		private int seedItemId = -1;
		private String payment;
		private String paymentItem;

		Step(Patch patch, String teleport, String seed, String compost)
		{
			this.patch = patch;
			this.teleport = teleport;
			this.seed = seed;
			this.compost = compost;
		}

		Step withTeleport(TeleportOption option, OwnedItems.Entry item)
		{
			this.teleportOption = option;
			if (item != null)
			{
				this.teleportItem = item.getName();
				this.teleportItemId = item.getId();
			}
			return this;
		}

		Step withSeedId(int id)
		{
			this.seedItemId = id;
			return this;
		}

		public Patch getPatch()
		{
			return patch;
		}

		/** De gekozen teleport-optie, of null. */
		public TeleportOption getTeleportOption()
		{
			return teleportOption;
		}

		/** Exacte naam van het teleport-item (bijv. "Skills necklace(4)"), of null bij spreuk/spirit tree. */
		public String getTeleportItem()
		{
			return teleportItem;
		}

		public int getTeleportItemId()
		{
			return teleportItemId;
		}

		public int getSeedItemId()
		{
			return seedItemId;
		}

		/** Betaling voor de gardener (bijv. "10 cactus spines"), of null. */
		public String getPayment()
		{
			return payment;
		}

		void setPayment(String payment, String paymentItem)
		{
			this.payment = payment;
			this.paymentItem = paymentItem;
		}

		/** Item waarmee je de gardener betaalt (bijv. "Cactus spine"), of null. */
		public String getPaymentItem()
		{
			return paymentItem;
		}

		/** null = geen teleport gevonden. */
		public String getTeleport()
		{
			return teleport;
		}

		/** null = geen zaad meer over voor deze patch. */
		public String getSeed()
		{
			return seed;
		}

		/** null = geen compost meer over. */
		public String getCompost()
		{
			return compost;
		}
	}

	private final RunType runType;
	private final int farmingLevel;
	private final Language language;
	private final List<Step> steps = new ArrayList<>();
	private final Map<String, Integer> withdraw = new LinkedHashMap<>();
	private final Set<Integer> highlightIds = new HashSet<>();
	private final Map<String, Integer> withdrawIds = new java.util.HashMap<>();
	private final Map<String, String> anyChargePrefix = new java.util.HashMap<>();
	private final List<String> warnings = new ArrayList<>();
	private final List<String> tips = new ArrayList<>();
	private final List<String> saplingAdvice = new ArrayList<>();
	private final List<String> seedOverview = new ArrayList<>();
	private double xpNow;
	private double xpLater;

	FarmPlan(RunType runType, int farmingLevel, Language language)
	{
		this.language = language;
		this.runType = runType;
		this.farmingLevel = farmingLevel;
	}

	void addStep(Step step)
	{
		steps.add(step);
	}

	void withdraw(OwnedItems.Entry item, int amount)
	{
		withdraw.merge(item.getName(), amount, Integer::sum);
		highlightIds.add(item.getId());
		withdrawIds.put(item.getName(), item.getId());
	}

	/** Voor herbruikbare items: hooguit 1 meenemen. */
	void withdrawOnce(OwnedItems.Entry item)
	{
		withdraw.putIfAbsent(item.getName(), 1);
		highlightIds.add(item.getId());
		withdrawIds.put(item.getName(), item.getId());
	}

	/**
	 * Dit item mag met elke lading meetellen, bijv. "Games necklace(" voor Games necklace(1) t/m (8).
	 */
	void allowAnyCharge(String itemName, String prefixPattern)
	{
		if (prefixPattern.endsWith("(") || prefixPattern.endsWith("*"))
		{
			anyChargePrefix.put(itemName, prefixPattern.endsWith("*")
				? prefixPattern.substring(0, prefixPattern.length() - 1)
				: prefixPattern);
		}
	}

	/**
	 * Hoeveel heb je van dit meeneem-item bij je?
	 *
	 * @param carried itemnaam (kleine letters) -> aantal, uit je inventory en equipment
	 */
	public int countCarried(String itemName, Map<String, Integer> carried)
	{
		String prefix = anyChargePrefix.get(itemName);
		if (prefix == null)
		{
			return carried.getOrDefault(itemName.toLowerCase(java.util.Locale.ROOT), 0);
		}
		String p = prefix.toLowerCase(java.util.Locale.ROOT);
		int total = 0;
		for (Map.Entry<String, Integer> e : carried.entrySet())
		{
			if (e.getKey().startsWith(p))
			{
				total += e.getValue();
			}
		}
		return total;
	}

	/** Item-ID's die je nog niet (genoeg) bij je hebt: die worden in de bank gemarkeerd. */
	public Set<Integer> missingIds(Map<String, Integer> carried)
	{
		Set<Integer> result = new HashSet<>();
		for (Map.Entry<String, Integer> e : withdraw.entrySet())
		{
			if (countCarried(e.getKey(), carried) < e.getValue())
			{
				Integer id = withdrawIds.get(e.getKey());
				if (id != null)
				{
					result.add(id);
				}
			}
		}
		return result;
	}

	void warn(String warning)
	{
		if (!warnings.contains(warning))
		{
			warnings.add(warning);
		}
	}

	void tip(String tip)
	{
		tips.add(tip);
	}

	void addXp(double now, double later)
	{
		xpNow += now;
		xpLater += later;
	}

	/** XP die je deze run krijgt (planten + compost). */
	public double getXpNow()
	{
		return xpNow;
	}

	/** XP die je later krijgt (Check-health bij bomen, oogsten bij herbs - geschat). */
	public double getXpLater()
	{
		return xpLater;
	}

	public List<String> getSaplingAdvice()
	{
		return saplingAdvice;
	}

	public List<String> getSeedOverview()
	{
		return seedOverview;
	}

	/** Taal waarin de teksten van dit plan staan. */
	public Language getLanguage()
	{
		return language;
	}

	public RunType getRunType()
	{
		return runType;
	}

	public int getFarmingLevel()
	{
		return farmingLevel;
	}

	public List<Step> getSteps()
	{
		return steps;
	}

	public Map<String, Integer> getWithdraw()
	{
		return withdraw;
	}

	public Set<Integer> getHighlightIds()
	{
		return highlightIds;
	}

	public List<String> getWarnings()
	{
		return warnings;
	}

	public List<String> getTips()
	{
		return tips;
	}

	/** Alleen de stappen waar echt iets geplant wordt, in route-volgorde. */
	public List<Step> getActiveSteps()
	{
		List<Step> result = new ArrayList<>();
		for (Step s : steps)
		{
			if (s.seed != null)
			{
				result.add(s);
			}
		}
		return result;
	}

	/** Aantal patches waar echt iets geplant wordt. */
	public int getPlantedCount()
	{
		int n = 0;
		for (Step s : steps)
		{
			if (s.seed != null)
			{
				n++;
			}
		}
		return n;
	}
}

package com.farmplanner;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(FarmPlannerConfig.GROUP)
public interface FarmPlannerConfig extends Config
{
	String GROUP = "banktopatch";

	@ConfigItem(
		keyName = "language",
		name = "Language / Taal",
		description = "Language of the side panel and plan / Taal van het paneel en het plan",
		position = 0
	)
	default Language language()
	{
		return Language.ENGLISH;
	}

	@ConfigItem(
		keyName = "highlightBank",
		name = "Highlight in bank",
		description = "Highlight the items you need to take in your bank and inventory",
		position = 1
	)
	default boolean highlightBank()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "highlightColor",
		name = "Highlight color",
		description = "Color of the highlights",
		position = 2
	)
	default Color highlightColor()
	{
		return new Color(0, 255, 120, 200);
	}

	@ConfigItem(
		keyName = "highlightTeleport",
		name = "Highlight teleport choice",
		description = "Colors the right option in the right-click menu and in the teleport window",
		position = 10
	)
	default boolean highlightTeleport()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightPatches",
		name = "Highlight patches",
		description = "Highlight the farming patches of your run in the world",
		position = 11
	)
	default boolean highlightPatches()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hintArrow",
		name = "Arrow to patch",
		description = "Show a yellow arrow (also on the minimap) to the nearest patch",
		position = 12
	)
	default boolean hintArrow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "payProtection",
		name = "Pay for tree protection",
		description = "Take the gardener's payment (e.g. 10 cactus spines per Yew) so your trees can't die",
		position = 14
	)
	default boolean payProtection()
	{
		return true;
	}

	@ConfigItem(
		keyName = "coinsPerTree",
		name = "Coins per tree",
		description = "Coins to take per (fruit) tree to have the gardener remove the old tree",
		position = 13
	)
	default int coinsPerTree()
	{
		return 200;
	}

	@ConfigItem(
		keyName = "useSpells",
		name = "Use teleport spells",
		description = "Use spells (with runes from your bank) when you have no teleport item",
		position = 3
	)
	default boolean useSpells()
	{
		return true;
	}

	@ConfigItem(
		keyName = "houseInHosidius",
		name = "House in Hosidius",
		description = "Use 'Teleport to house' for the Hosidius patch",
		position = 4
	)
	default boolean houseInHosidius()
	{
		return false;
	}

	@ConfigItem(
		keyName = "includeTrollheim",
		name = "Trollheim herb patch",
		description = "Include the Trollheim herb patch (requires My Arm's Big Adventure)",
		position = 5
	)
	default boolean includeTrollheim()
	{
		return false;
	}

	@ConfigItem(
		keyName = "includeLletya",
		name = "Lletya fruit tree patch",
		description = "Include the Lletya fruit tree patch (requires Mourning's End Part I)",
		position = 6
	)
	default boolean includeLletya()
	{
		return false;
	}
}

package com.farmplanner;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.Map;
import java.util.function.ToIntFunction;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTabbedPane;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class FarmPlannerPanel extends PluginPanel
{
	private static final int TEXT_WIDTH = 165;
	private static final Color DONE_BG = new Color(28, 70, 38);
	private static final Color DONE_TEXT = new Color(120, 230, 140);
	private static final Color CURRENT_BG = new Color(75, 65, 20);
	private static final Color CURRENT_BORDER = new Color(255, 200, 40);
	/** Groen: heb je bij je. Oranje: mis je nog. */
	private static final String HAVE_HEX = "#78e68c";
	private static final String MISSING_HEX = "#ffaa5a";

	private final FarmPlannerPlugin plugin;
	private final JLabel status = new JLabel();
	private final JPanel content = new JPanel();
	private final JButton planButton = new JButton();
	private final JButton clearButton = new JButton();
	private final JTabbedPane tabs = new JTabbedPane();
	private final JPanel saplingContent = new JPanel();
	private final JButton saplingPlanButton = new JButton();
	private final JButton saplingClearButton = new JButton();
	private boolean showingSaplingIntro = true;
	private boolean bankSeen;
	/** Laatst getoonde plan, zodat de tekst bij een taalwissel ververst kan worden. */
	private boolean showingIntro = true;

	FarmPlannerPanel(FarmPlannerPlugin plugin)
	{
		this.plugin = plugin;
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setLayout(new BorderLayout(0, 10));

		JLabel title = new JLabel("Bank to Patch");
		title.setFont(FontManager.getRunescapeBoldFont());
		JPanel header = new JPanel(new GridLayout(0, 1, 0, 4));
		header.add(title);
		header.add(status);

		// ---- Tabblad Run
		JComboBox<RunType> runSelect = new JComboBox<>(RunType.values());
		planButton.addActionListener(e ->
		{
			showMessage(lang().t("Working...", "Bezig..."));
			plugin.requestPlan((RunType) runSelect.getSelectedItem());
		});
		clearButton.addActionListener(e ->
		{
			plugin.clearPlan();
			showMessage(lang().t("Run stopped. Highlights are off.", "Run gestopt. Highlights zijn uit."));
		});
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		JPanel runTab = tab(runSelect, planButton, clearButton, content);

		// ---- Tabblad Saplings
		JComboBox<RunType> saplingSelect = new JComboBox<>(new RunType[]{RunType.TREE, RunType.FRUIT_TREE});
		saplingPlanButton.addActionListener(e ->
		{
			showSaplingMessage(lang().t("Working...", "Bezig..."));
			plugin.requestSaplingPlan((RunType) saplingSelect.getSelectedItem());
		});
		saplingClearButton.addActionListener(e ->
		{
			plugin.clearSaplingPlan();
			showSaplingIntro();
		});
		saplingContent.setLayout(new BoxLayout(saplingContent, BoxLayout.Y_AXIS));
		JPanel saplingTab = tab(saplingSelect, saplingPlanButton, saplingClearButton, saplingContent);

		tabs.addTab("Run", runTab);
		tabs.addTab("Saplings", saplingTab);
		tabs.addChangeListener(e -> plugin.setSaplingTabActive(tabs.getSelectedIndex() == 1));

		add(header, BorderLayout.NORTH);
		add(tabs, BorderLayout.CENTER);

		applyLanguage();
		showSaplingIntro();
	}

	/** Eén tabblad: keuzelijst, twee knoppen en een inhoud-deel. */
	private static JPanel tab(JComboBox<RunType> select, JButton make, JButton stop, JPanel body)
	{
		JPanel buttons = new JPanel(new GridLayout(1, 2, 5, 0));
		buttons.add(make);
		buttons.add(stop);
		JPanel top = new JPanel(new GridLayout(0, 1, 0, 6));
		top.add(select);
		top.add(buttons);

		JPanel tab = new JPanel(new BorderLayout(0, 8));
		tab.setBorder(new EmptyBorder(8, 0, 0, 0));
		tab.add(top, BorderLayout.NORTH);
		tab.add(body, BorderLayout.CENTER);
		return tab;
	}

	private Language lang()
	{
		return plugin.getLanguage();
	}

	/** Zet de vaste teksten (knoppen, status, intro) in de gekozen taal. */
	void applyLanguage()
	{
		Language l = lang();
		planButton.setText(l.t("Make plan", "Maak plan"));
		clearButton.setText(l.t("Stop run", "Stop run"));
		saplingPlanButton.setText(l.t("Make plan", "Maak plan"));
		saplingClearButton.setText(l.t("Stop", "Stop"));
		tabs.setTitleAt(0, l.t("Farm run", "Farm run"));
		tabs.setTitleAt(1, l.t("Saplings", "Saplings"));
		setBankSeen(bankSeen);
		if (showingIntro)
		{
			showIntro();
		}
		if (showingSaplingIntro)
		{
			showSaplingIntro();
		}
	}

	// ------------------------------------------------------------------ tabblad Saplings

	private void showSaplingIntro()
	{
		showSaplingMessage(lang().t(
			"Turn your tree seeds into saplings.<br><br>"
				+ "Choose trees or fruit trees and click 'Make plan'. The plugin picks your best seeds for one "
				+ "inventory, shows what to take and highlights the items for the next action.",
			"Maak saplings van je boomzaden.<br><br>"
				+ "Kies bomen of fruitbomen en klik op 'Maak plan'. De plugin kiest je beste zaden voor één "
				+ "inventory, laat zien wat je moet meenemen en markeert de items voor de volgende actie."));
		showingSaplingIntro = true;
	}

	void showSaplingMessage(String html)
	{
		showingSaplingIntro = false;
		saplingContent.removeAll();
		saplingContent.add(block(html, ColorScheme.DARKER_GRAY_COLOR, ColorScheme.LIGHT_GRAY_COLOR));
		saplingContent.revalidate();
		saplingContent.repaint();
	}

	void showSaplingPlan(SaplingPlan plan, Map<String, Integer> carried)
	{
		showingSaplingIntro = false;
		saplingContent.removeAll();
		Language l = plan.getLanguage();

		if (!plan.getBatches().isEmpty())
		{
			// ---- Wat ga je maken
			StringBuilder b = new StringBuilder();
			for (SaplingPlan.Batch batch : plan.getBatches())
			{
				b.append(batch.getAmount()).append(" x ").append(esc(batch.getSeed().getItemName())).append("<br>");
			}
			b.append(l.t("XP when planted + checked: <b>", "XP als je ze plant + check-health: <b>"))
				.append(l.number(plan.getXp())).append("</b>");
			saplingContent.add(header(l.t("YOU WILL MAKE", "JE GAAT MAKEN")));
			saplingContent.add(block(b.toString(), ColorScheme.DARKER_GRAY_COLOR, ColorScheme.LIGHT_GRAY_COLOR));

			// ---- Voortgang en volgende actie
			SaplingPlan.Progress p = plan.progress(carried);
			String next;
			switch (p.next)
			{
				case PLANT:
					next = l.t("Use a seed on a filled Plant pot (trowel in your inventory).",
						"Gebruik een zaad op een gevulde Plant pot (trowel in je inventory).");
					break;
				case WATER:
					next = l.t("Water your seedlings with the Watering can.",
						"Geef je seedlings water met de Watering can.");
					break;
				case WAIT:
					next = l.t("Wait a few minutes: the watered seedlings turn into saplings (also in your bank).",
						"Wacht een paar minuten: de gewaterde seedlings worden saplings (ook in je bank).");
					break;
				case DONE:
					next = l.t("All done! Your saplings are ready to plant on a tree run.",
						"Klaar! Je saplings kunnen geplant worden tijdens een tree run.");
					break;
				default:
					next = l.t("Take the items below from your bank.", "Haal de items hieronder uit je bank.");
					break;
			}
			StringBuilder prog = new StringBuilder();
			prog.append("<b>").append(l.t("Next: ", "Volgende: ")).append("</b>").append(esc(next)).append("<br><br>");
			prog.append(l.t("Seeds: ", "Zaden: ")).append(p.seeds)
				.append(l.t(" - filled pots: ", " - gevulde potten: ")).append(p.pots).append("<br>");
			prog.append(l.t("Seedlings without water: ", "Seedlings zonder water: ")).append(p.dry).append("<br>");
			prog.append(l.t("Growing: ", "Groeien: ")).append(p.growing).append("<br>");
			prog.append(l.t("Saplings ready: ", "Saplings klaar: ")).append("<b>").append(p.saplings).append("</b>");
			boolean done = p.next == SaplingPlan.Action.DONE;
			saplingContent.add(header(l.t("PROGRESS", "VOORTGANG")));
			saplingContent.add(block(prog.toString(), done ? DONE_BG : CURRENT_BG, done ? DONE_TEXT : Color.WHITE));

			// ---- Meenemen
			addTakeList(saplingContent, l, plan.getWithdraw(), name -> plan.countCarried(name, carried));
		}

		if (!plan.getWarnings().isEmpty())
		{
			saplingContent.add(header(l.t("WARNING", "LET OP")));
			saplingContent.add(block(list(plan.getWarnings(), "! "), ColorScheme.DARKER_GRAY_COLOR,
				new Color(255, 170, 90)));
		}
		if (!plan.getInfo().isEmpty())
		{
			saplingContent.add(header(l.t("OTHER SEEDS", "OVERIGE ZADEN")));
			saplingContent.add(block(list(plan.getInfo(), "- "), ColorScheme.DARKER_GRAY_COLOR,
				ColorScheme.LIGHT_GRAY_COLOR));
		}

		saplingContent.add(header(l.t("HOW IT WORKS", "ZO WERKT HET")));
		saplingContent.add(block(list(java.util.Arrays.asList(
			l.t("1. Use the tree seed on a filled Plant pot (Gardening trowel in your inventory).",
				"1. Gebruik het boomzaad op een gevulde Plant pot (Gardening trowel in je inventory)."),
			l.t("2. Use the Watering can on the seedling.", "2. Gebruik de Watering can op de seedling."),
			l.t("3. After a few minutes the seedling becomes a sapling, also in your bank.",
				"3. Na een paar minuten wordt de seedling een sapling, ook in je bank.")), ""),
			ColorScheme.DARKER_GRAY_COLOR, ColorScheme.LIGHT_GRAY_COLOR));

		saplingContent.revalidate();
		saplingContent.repaint();
	}

	// ------------------------------------------------------------------ run klaar

	/** Alle stappen zijn gedaan: samenvatting, highlights zijn al uit. */
